sitAtTable=function(tableId){originalSitAtTable(tableId);loadFreshPourNote(true);};
// Intake may add information, but must never overwrite consent, client status,
// or Do Not Contact protections on an existing contact.
window.AgentRise.captureLead=async function(lead={}){
 if(!pilot.loaded)return {saved:false,reason:'Sign in before importing a lead.'};
 const clean=k=>String(lead[k]??'').trim();const email=clean('email').toLowerCase(),phone=clean('phone');
 if(!email&&!phone)return {saved:false,reason:'An email address or phone number is required.'};
 const existing=findDuplicateContact(phone,email),name=leadNameParts(clean('name'));
 if(existing){existing.notes=[existing.notes,clean('notes')].filter(Boolean).join('\n');existing.source=mergeSources(existing.source,clean('source'));}
 else state.prospects.unshift(normalizeProspect({id:uid(),firstName:clean('firstName')||name.firstName,lastName:clean('lastName')||name.lastName,phone,email,product:clean('product'),source:clean('source'),notes:clean('notes'),leadPool:'Contact Review Pool',qualificationStatus:'Review Needed',marketingEligibility:'Review Needed',status:'New Lead',createdAt:iso()}));
 const saved=await persistWorkspace();redraw();return {saved,updated:!!existing,preview:pilot.demo};
};
